$script:Esc = [string][char]27
$script:UiLang = 'en'
$script:Color = $false
$script:Utf = $false
$script:TrueColor = $false
$script:LogReady = $false
$script:Warnings = New-Object System.Collections.Generic.List[string]
$script:BannerDone = $false
$script:Spinner = $null
$script:Bs = $null
$script:DbBackup = ''
$script:PanelTried = $false
$script:Rel = $null
